package com.careerpilot.modules.scheduling.controller;import com.careerpilot.modules.assessment.dto.AttemptResponse;import com.careerpilot.modules.scheduling.dto.*;import com.careerpilot.modules.scheduling.service.ScheduledExamService;import com.careerpilot.security.CurrentUser;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/v1/student/scheduled-exams")public class StudentScheduledExamController{private final ScheduledExamService service;public StudentScheduledExamController(ScheduledExamService s){service=s;}@PostMapping@ResponseStatus(HttpStatus.CREATED)public StudentScheduledExamResponse create(@Valid@RequestBody CreateScheduledExamRequest r){return service.create(CurrentUser.require(),r);}@GetMapping public List<StudentScheduledExamResponse>list(){return service.list(CurrentUser.require());}@GetMapping("/{id}")public StudentScheduledExamResponse get(@PathVariable UUID id){return service.get(CurrentUser.require(),id);}@PatchMapping("/{id}/reschedule")public StudentScheduledExamResponse reschedule(@PathVariable UUID id,@Valid@RequestBody RescheduleExamRequest r){return service.reschedule(CurrentUser.require(),id,r);}@PostMapping("/{id}/cancel")public StudentScheduledExamResponse cancel(@PathVariable UUID id){return service.cancel(CurrentUser.require(),id);}@PostMapping("/{id}/start")public AttemptResponse start(@PathVariable UUID id){return service.start(CurrentUser.require(),id);}}
